INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(127562, 'ruRU', '', 'Лучше не испытывай моё терпение! Шторм отвечает на мой зов!', 24330),
(127582, 'ruRU', '', 'Д\'Бинн и я отправимся в охотничий дом, если понадобимся тебе.', 24330),
(127583, 'ruRU', '', 'Берегись, народ, Клунк вас сейчас отклункает!', 24330),
(127585, 'ruRU', '', 'Вместе мы защитим наш дом от Пылающего Легиона.', 24330),
(127586, 'ruRU', '', 'Нас не остановить!', 24330),
(127592, 'ruRU', '', 'Угрозу нужно устранить. Действуй быстро.', 24330),
(127593, 'ruRU', '', 'Угроза нависает рядом. Уничтожь цель.', 24330),
(127594, 'ruRU', '', 'Время передать послание Легиону. Отправь этого обратно по кусочкам!', 24330),
(127595, 'ruRU', '', 'У нас много дел. Подари этому демону быструю смерть.', 24330),
(127596, 'ruRU', '', 'Наши разведчики сообщают о серьёзной угрозе в этом районе. Уничтожь её!', 24330),
(127597, 'ruRU', '', 'Прямо впереди... новая цель. Отправь её с воплями обратно в Круговерть Пустоты!', 24330),
(127598, 'ruRU', '', 'Демоны размножаются, как крысы. Убей этого, прежде чем он призовёт больше своей мерзкой родни в наш мир!', 24330),
(127599, 'ruRU', '', 'Мощная угроза таится рядом. Найди её и уничтожь!', 24330),
(127600, 'ruRU', '', 'Хороший удар, защитник. Оставайся начеку.', 24330),
(127601, 'ruRU', '', 'Достойный конец для мерзкого захватчика.', 24330),
(127602, 'ruRU', '', 'Послание доставлено!', 24330),
(127603, 'ruRU', '', 'Это было больше милосердия, чем заслуживала эта тварь. К следующей цели!', 24330),
(127604, 'ruRU', '', 'Впечатляет! У этого негодяя не было ни единого шанса.', 24330),
(127605, 'ruRU', '', 'Отлично сработано! Твои навыки острее любого оружия Легиона.', 24330),
(127606, 'ruRU', '', 'Победа за победой, мы отбрасываем волну этого вторжения. Отлично сработано!', 24330),
(127607, 'ruRU', '', 'Ещё одна угроза уничтожена. Превосходно!', 24330),
(127650, 'ruRU', '', 'Я скормлю тебя скакунам ужаса!', 24330),
(127651, 'ruRU', '', 'Хел\'нурат будет охотиться на тебя, $c...', 24330),
(127675, 'ruRU', '', 'Тебе не сравниться со мной и моими псами!', 24330),
(127676, 'ruRU', '', 'У тебя никогда не будет шанса против Легиона!', 24330),
(127677, 'ruRU', '', 'Ты ОТДАШЬ мне то, что я хочу, демон.', 24330),
(127678, 'ruRU', '', 'Мне не откажут. Говори.', 24330),
(127679, 'ruRU', '', 'Что они планируют, демон?', 24330),
(127680, 'ruRU', '', 'Я устал от этих игр. Говори, или умри.', 24330),
(127681, 'ruRU', '', 'Говори!', 24330),
(127682, 'ruRU', '', 'Мне становится скучно. Расскажи нам то, что мы хотим знать, или встретишь свою гибель.', 24330),
(127689, 'ruRU', '', 'Тебе не так легко отделаться от Мрачного Тотема, дитя. Мы заслужим своё место.', 24330),
(127696, 'ruRU', '', 'Ты не пожалеешь об этом выборе, Клинок Тени. Я уничтожу любого демона Легиона или заговорщика, который встанет на моём пути!', 24330),
(127715, 'ruRU', '', 'Я слышала рог Слоди. Полагаю, ты тот самый чужак, о котором он объявлял?', 24330),
(127717, 'ruRU', '', 'Я знакома с пророчеством Фалдроттин о валькирах, но не читала сам текст. Дай мне взглянуть на найденные тобой свитки.\n\n<Брина внимательно изучает текст свитков.>\n\nЕсли эти свитки верны, это значит, что среди нас может быть наследник Сковальда! Независимо от того, во что верят валькиры, ты оказал бы нам услугу, убрав её отсюда.\n\nНайди Ингвильд в башне, что возвышается над городом. Она внимательно следит за тем, кто приходит и уходит из Джандвика, и наверняка заметила бы, если кто-то значимый недавно побывал здесь.', 24330),
(127718, 'ruRU', '', 'Я слежу за тобой, чужак.', 24330),
(127720, 'ruRU', '', 'На самом деле, да, кое-что есть.\n\nНедавно здесь проходила странствующая дева-щитоносица и разбила лагерь за городом. Она задержалась ровно настолько, чтобы купить припасы, и всё это время избегала смотреть в глаза.\n\nЯ собиралась проверить, зачем она здесь, но ты можешь сходить вместо меня. Её лагерь найдёшь на пляже к востоку.', 24330),
(127736, 'ruRU', '', 'Значит, ты не встретишься со мной в одиночном бою? Священные кости наших предков содрогнулись бы от такого бесчестья!', 24330),
(127737, 'ruRU', '', 'Если ты не окажешь мне чести, тогда я сломаю тебя! Защитник, помоги мне прикончить эту псину!', 24330),
(127749, 'ruRU', '', 'Какие сюрпризы нас ждут?', 24330);
